export function normalizeSkill(value) {
  const name = String(value?.name || '').trim().slice(0, 64);
  const instructions = String(value?.instructions || '').trim();
  if (!name || !instructions || instructions.length > 16000) throw new Error('skill_invalid');
  const resources = normalizeSkillResources(value.resources);
  if (new TextEncoder().encode(JSON.stringify({instructions, resources})).length > SKILL_PACKAGE_LIMIT) throw new Error('skill_invalid');
  const automatic = value.toolMode === 'automatic';
  return {id: typeof value.id === 'string' && /^custom-[\w-]+$/.test(value.id) ? value.id : `custom-${crypto.randomUUID()}`, name, instructions, description: String(value.description || '내 스킬').trim().slice(0, 1024), compatibility: String(value.compatibility || '').trim().slice(0, 500), resources, ...(automatic ? {toolMode: 'automatic'} : {}), needsPage: !automatic && (value.needsPage === true || value.allowFill === true || value.allowStorage === true || value.allowAutomation === true), allowStorage: automatic || value.allowStorage === true, allowFill: automatic || value.allowFill === true || value.allowAutomation === true, allowAutomation: automatic || value.allowAutomation === true};
}
// Skills describe a workflow. New/edited definitions use the normal copilot
// catalog; browser grants, target ownership and final-action approval stay in
// the host. Legacy definitions keep their behavior until explicitly edited.
export const automaticSkillTools = skill => !skill || skill.toolMode === 'automatic';
export const taskSkillId = (task, activeId = '') => task ? task.autoConnect && (!task.skillId || task.skillId === 'browser-agent') ? '' : task.skillId : activeId;
export function allSkills(custom = []) {
  return [...BUILTIN_SKILLS, ...custom.slice(0, 20).flatMap(value => {try {return [normalizeSkill(value)];} catch {return [];}})];
}
export function importSkill(text, filename = '내 스킬') {
  if (text.length > SKILL_PACKAGE_LIMIT + 16000) throw new Error('skill_invalid');
  if (text.trimStart().startsWith('{')) {
    let value;
    try {value = JSON.parse(text);} catch {throw new Error('skill_invalid');}
    if (!['nubi-browser-skill', 'aipro-browser-skill'].includes(value.format) || !(value.version === 1 || value.format === 'nubi-browser-skill' && value.version === 2)) throw new Error('skill_invalid');
    return normalizeSkill({name: value.name, instructions: value.instructions, description: value.description, compatibility: value.compatibility, resources: value.resources, toolMode: value.toolMode, needsPage: value.capabilities?.page === true, allowStorage: value.capabilities?.storage === true, allowFill: value.capabilities?.fill === true, allowAutomation: value.capabilities?.automation === true});
  }
  return normalizeSkill(parseSkillMarkdown(text, filename));
}
export async function importSkillFolder(files) {return normalizeSkill(await readSkillFolder(files));}

export function exportSkill(value) {
  const skill = normalizeSkill(value);
  // A shared definition contains no runtime IDs, page values, credentials or history.
  return JSON.stringify({format: 'nubi-browser-skill', version: 2, name: skill.name, description: skill.description, compatibility: skill.compatibility, instructions: skill.instructions, resources: skill.resources, ...(skill.toolMode === 'automatic' ? {toolMode: 'automatic'} : {capabilities: {page: skill.needsPage, storage: skill.allowStorage, fill: skill.allowFill, automation: skill.allowAutomation}})}, null, 2);
}

