export function clarificationTool(images) {
  return {type: 'function', function: {name: 'ask_user',
    description: QUESTION_GUIDANCE + ' Pause execution until the user answers.' + (images ? ' image_refs from the latest find_images show actual preview/download choices. Never combine choices and image_refs.' : ''),
    parameters: {type: 'object', properties: {
      question: {type: 'string', maxLength: 180},
      choices: {type: 'array', minItems: 2, maxItems: 4, items: {type: 'object', properties: {label: {type: 'string', maxLength: 80}, description: {type: 'string', maxLength: 160}}, required: ['label'], additionalProperties: false}},
      input_mode: {type: 'string', enum: ['text', 'long_text']},
      input_placeholder: {type: 'string', minLength: 1, maxLength: 100, description: 'Optional short format cue for the answer, not prefilled content. One line.'},
      ...(images ? {image_refs: {type: 'array', minItems: 2, maxItems: 4, items: {type: 'string', maxLength: 200}}} : {}),
    }, required: ['question'], additionalProperties: false},
  }};
}
